'use strict';

// Reads the bank's CSV export into one object per row, keyed by the header line.
function parseCsv(text) {
  const lines = text.split(/\r?\n/).filter((line) => line.trim() !== '');
  if (lines.length === 0) return [];
  const header = lines[0].split(',').map((h) => h.trim());
  return lines.slice(1).map((line) => {
    const cells = line.split(',');
    const row = {};
    header.forEach((name, i) => {
      row[name] = (cells[i] || '').trim();
    });
    return row;
  });
}

module.exports = { parseCsv };
'use strict';

function formatMoney(value) {
  return value.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// Two columns: names on the left, amounts right-aligned.
function formatTable(entries) {
  const width = Math.max(...entries.map(([name]) => name.length));
  const amounts = entries.map(([, value]) => formatMoney(value));
  const amountWidth = Math.max(...amounts.map((a) => a.length));
  return entries
    .map(([name], i) => name.padEnd(width) + '  ' + amounts[i].padStart(amountWidth))
    .join('\n');
}

module.exports = { formatMoney, formatTable };
'use strict';

// Totals per category, in the order categories first appear.
function summarize(rows) {
  const totals = new Map();
  for (const row of rows) {
    const category = row.Category || 'Other';
    const amount = parseFloat(row.Amount);
    totals.set(category, (totals.get(category) || 0) + amount);
  }
  return totals;
}

function grandTotal(totals) {
  let sum = 0;
  for (const value of totals.values()) sum += value;
  return sum;
}

module.exports = { summarize, grandTotal };
#!/usr/bin/env node
'use strict';

const fs = require('fs');
const { parseCsv } = require('../src/csv');
const { summarize, grandTotal } = require('../src/summary');
const { formatTable } = require('../src/format');

const file = process.argv[2];
if (!file) {
  console.error('usage: node bin/summary.js <statement.csv>');
  process.exit(1);
}

const rows = parseCsv(fs.readFileSync(file, 'utf8'));
const totals = summarize(rows);
const entries = [...totals.entries()].sort((a, b) => b[1] - a[1]);
entries.push(['Total', grandTotal(totals)]);

console.log(`${rows.length} transactions in ${file}\n`);
console.log(formatTable(entries));
